static size_t count_unique_positive_ids(const int32_t *packet_ids, size_t packet_count)
{
	if (packet_count == 0) {
		return 0;
	}

	int32_t unique_positive_ids[packet_count];
	size_t unique_count = 0;

	for (size_t i = 0; i < packet_count; i++) {
		if (packet_ids[i] <= 0) {
			continue; // Skip FIN packets and non-positive IDs
		}

		bool is_unique = true;
		for (size_t j = 0; j < unique_count; j++) {
			if (unique_positive_ids[j] == packet_ids[i]) {
				is_unique = false;
				break;
			}
		}

		if (is_unique) {
			unique_positive_ids[unique_count++] = packet_ids[i];
		}
	}
	return unique_count;
}

